(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025-t*0.4)*8 + Math.cos(my*0.03+t*0.35)*6;
  const w2y = Math.cos(my*0.022+t*0.32)*8 + Math.sin(mx*0.028-t*0.38)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.55)*110, 80+Math.cos(t*0.38)*55, 0.075, 2.1, 0.6],
    [320+Math.cos(t*0.48)*100, 160+Math.sin(t*0.65)*55, 0.09, 1.8, 0.5],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.055, 2.4, 0.7],
    [100+Math.cos(t*0.75+1)*90, 190+Math.sin(t*0.58+3)*65, 0.11, 1.6, 0.4],
    [380+Math.sin(t*0.42+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 0.65],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.52)*85, 0.085, 2.0, 0.55],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*50, 0.1, 1.9, 0.45],
    [420+Math.cos(t*0.35+2)*60, 200+Math.sin(t*0.45+4)*55, 0.07, 2.2, 0.6]
  ];
  let aS=0, iS=0, crossA=0, crossI=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,w]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp), wave2=Math.cos(d*f*0.7+t*sp*0.6+1.5);
    aS+=wave*w; iS+=wave2*w;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2,w2]=src[j];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      crossA+=Math.sin((d*f-t*sp)+(d2*f2-t*sp2))*0.15*w*w2;
      crossI+=Math.cos((d*f*0.7+t*sp*0.6)+(d2*f2*0.7+t*sp2*0.6))*0.12*w*w2;
    }
  }
  const tw=src.reduce((s,v)=>s+v[4],0);
  const act=aS/tw+crossA*0.5, inh=iS/tw+crossI*0.5;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    +Math.sin((sx+sy)*0.11+t*2.3)*0.2+Math.sin((sx-sy)*0.09-t*1.8)*0.2
    +Math.sin(sx*0.06+sy*0.08-t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1))*0.35
    +Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const lapAct=Math.sin(sx*0.12+t*0.8)+Math.sin(sy*0.12-t*0.9)+Math.sin((sx+sy)*0.085+t*0.7);
  const lapInh=Math.cos(sx*0.1-t*0.7)+Math.cos(sy*0.1+t*0.8)+Math.cos((sx-sy)*0.075-t*0.6);
  const feed=0.045+Math.sin(t*0.15)*0.01, kill=0.062+Math.cos(t*0.12)*0.008;
  const rd=Math.tanh((act*(1+feed)-inh*kill+bg*0.25+spiral*0.4+lapAct*0.15-lapInh*0.1)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.5+Math.sin(sx*0.2-sy*0.18+t*0.6)*0.3)*1.3)*0.25;
  const vort=Math.sin(ang*5+dist*0.04-t*2)*Math.exp(-dist*0.008)*0.2;
  const blend=rd*0.6+cell*0.2+vort*0.15+spiral*0.05, v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,42,88],[18,85,115],[25,138,128],[65,170,110],
    [180,185,60],[215,155,55],[210,110,65],[175,58,72],[110,30,65],
    [55,18,72],[15,12,58],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm=f*f*(3-2*f);
  const lum=0.75+Math.sin(rd*Math.PI)*0.25;
  const edge=Math.abs(rd)>0.65?1.18:Math.abs(rd)>0.4?1.05:0.95;
  const glow=Math.max(0,Math.abs(rd)-0.5)*0.6;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*50)|0)
  ];
}
